1	package agentusageview
2	
3	import (
4		"os"
5		"path/filepath"
6		"strings"
7		"testing"
8	
9		"github.com/anthnel/devdesk/internal/agentusage"
10		sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
11		"github.com/anthnel/devdesk/internal/ui/testutil"
12	)
13	
14	// Step 3 of DEVDESK-42: Rules 130, 123, 128 and 114 for the two levels.
15	
16	// openKey is the header entry that opens a session's agents.
17	const (
18		openKey  = "→"
19		closeKey = "esc"
20	)
21	
22	const wideID = "abcdef12-3456-4789-8abc-def012345678"
23	
24	// atAgents opens the first session (project "/srv/pa") and answers the parse.
25	func atAgents(t *testing.T, u agentusage.Usage) Model {
26		t.Helper()
27		m := withSessions(t, "/p/a.jsonl")
28		m, _ = opened(t, m, "right")
29		return answer(t, m, u)
30	}
31	
32	// agentsLoadingModel is the agents level before the parse answers.
33	func agentsLoadingModel(t *testing.T) Model {
34		t.Helper()
35		m, _ := opened(t, withSessions(t, "/p/a.jsonl"), "right")
36		return m
37	}
38	
39	// footerText is the whole footer, with the message line included.
40	func footerText(m Model) string { return m.RenderFooter(120) }
41	
42	// ── Rule 130: same keys, Disabled follows the level ──────────────────────────
43	
44	func TestAgentsLevelAdvertisesTheSameFiveKeys(t *testing.T) {
45		want := []string{"ctrl+r", openKey, closeKey, "/", "?"}
46		states := map[string]Model{
47			"sessions loading": newModel(t),
48			"sessions empty":   loaded(t, newModel(t)),
49			"sessions loaded":  withSessions(t, "/p/a.jsonl"),
50			"agents loading":   agentsLoadingModel(t),
51			"agents loaded":    atAgents(t, threeSubs()),
52		}
53		failed := atAgents(t, threeSubs())
54		failed = feed(t, failed, sessionUsageLoadedMsg{gen: failed.agentGen, err: os.ErrNotExist})
55		states["agents error"] = failed
56		states["agents filtering"] = feed(t, atAgents(t, threeSubs()), testutil.Key("/"))
57	
58		for name, m := range states {
59			got := testutil.ShortcutKeys(m.GetShortcuts())
60			if strings.Join(got, ",") != strings.Join(want, ",") {
61				t.Errorf("%s: keys %v, want %v", name, got, want)
62			}
63		}
64	}
65	
66	func TestShortcutsAreGreyedByLevelAndByRow(t *testing.T) {
67		tests := []struct {
68			name         string
69			m            Model
70			openEnabled  bool
71			closeEnabled bool
72		}{
73			{"sessions with a row", withSessions(t, "/p/a.jsonl"), true, false},
74			{"sessions with none", loaded(t, newModel(t)), false, false},
75			{"agents loading", agentsLoadingModel(t), false, true},
76			{"agents loaded", atAgents(t, threeSubs()), false, true},
77		}
78		for _, tt := range tests {
79			t.Run(tt.name, func(t *testing.T) {
80				s := tt.m.GetShortcuts()
81				for _, k := range []string{openKey, closeKey} {
82					if !testutil.HasShortcut(s, k) {
83						t.Fatalf("%q must be greyed, never dropped (Rule 130)", k)
84					}
85				}
86				if got := testutil.ShortcutEnabled(s, openKey); got != tt.openEnabled {
87					t.Errorf("%s enabled = %v, want %v", openKey, got, tt.openEnabled)
88				}
89				if got := testutil.ShortcutEnabled(s, closeKey); got != tt.closeEnabled {
90					t.Errorf("%s enabled = %v, want %v", closeKey, got, tt.closeEnabled)
91				}
92				for _, k := range []string{"ctrl+r", "/", "?"} {
93					if !testutil.ShortcutEnabled(s, k) {
94						t.Errorf("%q always acts, it must not be greyed", k)
95					}
96				}
97			})
98		}
99	}
100	
101	func TestAFilterMatchingNoSessionGreysOpen(t *testing.T) {
102		m := withSessions(t, "/p/a.jsonl")
103		m = feed(t, m, testutil.Key("/"))
104		for _, msg := range testutil.Type("zzz-no-match") {
105			m = feed(t, m, msg)
106		}
107		if len(m.table.Visible()) != 0 {
108			t.Fatalf("fixture error: the filter should match nothing, %d rows left", len(m.table.Visible()))
109		}
110		if !testutil.ShortcutDisabled(m.GetShortcuts(), openKey) {
111			t.Errorf("%s must be greyed when no row is selectable", openKey)
112		}
113	}
