115	func TestShortcutDescriptionsAtBothLevelsStartWithACapital(t *testing.T) {
116		for name, m := range map[string]Model{"sessions": withSessions(t, "/p/a.jsonl"), "agents": atAgents(t, threeSubs())} {
117			for _, s := range m.GetShortcuts() {
118				if s.Description == "" || s.Description[0] < 'A' || s.Description[0] > 'Z' {
119					t.Errorf("%s: %q description %q must start with a capital (Rule 137)", name, s.Key, s.Description)
120				}
121			}
122		}
123	}
