125	// ── Rule 130: a refusal says why, once, from the same Availability ───────────
126	
127	func TestOpeningWithNoSessionWarnsAndStays(t *testing.T) {
128		m := loaded(t, newModel(t))
129		next, cmd := opened(t, m, "right")
130		if next.level != levelSessions {
131			t.Fatalf("level = %v, want to stay on the sessions", next.level)
132		}
133		if cmd == nil {
134			t.Fatal("the refusal must come with its footer timer")
135		}
136		if !strings.Contains(footerText(next), reasonNoSession) {
