141	func TestOpeningInsideASessionWarnsAndStays(t *testing.T) {
142		for _, key := range []string{"right", "enter"} {
143			t.Run(key, func(t *testing.T) {
144				m := atAgents(t, threeSubs())
145				gen := m.agentGen
146				next, _ := opened(t, m, key)
147				if next.level != levelAgents || next.agentGen != gen {
148					t.Errorf("%s inside a session must change nothing (level %v, gen %d->%d)", key, next.level, gen, next.agentGen)
149				}
150				if !strings.Contains(footerText(next), reasonInsideSession) {
151					t.Errorf("footer lacks %q:\n%s", reasonInsideSession, footerText(next))
152				}
153			})
