157	func TestDotAtTheAgentsLevelIsRefusedWithAReason(t *testing.T) {
158		m := atAgents(t, threeSubs())
159		next, cmd := opened(t, m, ".")
160		if cmd == nil {
161			t.Fatal("the refusal must come with its footer timer")
162		}
163		if !strings.Contains(footerText(next), reasonAgentsUnsorted) {
164			t.Errorf("footer lacks %q:\n%s", reasonAgentsUnsorted, footerText(next))
165		}
166		before, after := m.agentTable.Visible(), next.agentTable.Visible()
167		for i := range before {
168			if before[i].ID != after[i].ID {
169				t.Fatalf("`.` must not reorder the tree: %v -> %v", before, after)
170			}
171		}
