174	func TestDotAtTheSessionsLevelStillCyclesTheSort(t *testing.T) {
175		m := withSessions(t, "/p/a.jsonl")
176		next, _ := opened(t, m, ".")
177		if strings.Contains(footerText(next), reasonAgentsUnsorted) {
178			t.Error("the agents-level refusal must not leak to the sessions level")
