182	func TestEscAtTheSessionsLevelIsSilent(t *testing.T) {
183		m := withSessions(t, "/p/a.jsonl")
184		next, cmd := opened(t, m, "esc")
185		if next.level != levelSessions {
186			t.Fatalf("level = %v", next.level)
187		}
188		if cmd != nil {
189			t.Error("esc at the top level is a silent no-op, with no footer timer")
190		}
191		if strings.Contains(footerText(next), reasonTopLevel) {
192			t.Errorf("footer must not name %q: a stray esc is not a refusal worth a line", reasonTopLevel)
