196	func TestEveryReasonIsAWarnNotAnError(t *testing.T) {
197		m := loaded(t, newModel(t))
198		m, _ = opened(t, m, "right")
199		if got := m.footer.View(120, sharedcomponents.Status{}); !strings.Contains(got, reasonNoSession) {
200			t.Fatalf("fixture error: %q not in %q", reasonNoSession, got)
201		}
202		if m.footer.Level() != sharedcomponents.LevelWarning {
203			t.Errorf("a refusal is a Warn (Rule 130), got level %v", m.footer.Level())
204		}
205	}
