220	func TestAgentsHeaderCountsAgentsAndTokens(t *testing.T) {
221		u := agentusage.Usage{Agents: []agentusage.Agent{
222			{Main: true, Models: []string{"model-a"}, Tokens: agentusage.Tokens{Input: 5000, Output: 1000}},
223			{ID: "a01", Type: "coder", Tokens: agentusage.Tokens{Output: 400}},
224			{ID: "a02", Type: "tester", Tokens: agentusage.Tokens{CacheRead: 300, Output: 100}},
