281	// ── Footer: breadcrumb (Rule 123), height (Rule 124) ─────────────────────────
282	
283	func TestFooterHeightGainsTheBreadcrumbAtTheAgentsLevel(t *testing.T) {
284		if got := withSessions(t, "/p/a.jsonl").GetFooterHeight(); got != 2 {
285			t.Errorf("sessions level footer = %d, want 2", got)
286		}
287		m := atAgents(t, threeSubs())
