291		m = feed(t, m, testutil.Key("/"))
292		if got := m.GetFooterHeight(); got != 3+m.agentTable.FilterBar().ExtraHeight() || got < 4 {
293			t.Errorf("agents level footer with the filter bar = %d, want at least 4", got)
