297	func TestBreadcrumbReadsSessionsProjectAndShortID(t *testing.T) {
298		home := os.Getenv("HOME")
299		s := session(wideID, filepath.Join(home, "w", "app"), 0)
300		s.Parent = "/p/a.jsonl"
301		m := loaded(t, newModel(t), s)
302		m, _ = opened(t, m, "right")
303	
304		lines := strings.Split(footerText(m), "\n")
305		if len(lines) != m.GetFooterHeight() {
306			t.Fatalf("footer has %d lines, budget is %d:\n%s", len(lines), m.GetFooterHeight(), footerText(m))
307		}
308		first := lines[0]
309		for _, want := range []string{"Sessions", "~/w/app", wideID[:8], "›"} {
310			if !strings.Contains(first, want) {
311				t.Errorf("breadcrumb line lacks %q: %q", want, first)
