359	func TestDegradedUsageWarnsThatTotalsAreApproximate(t *testing.T) {
360		m := atAgents(t, degraded())
361		st := m.status()
362		if st.Level != sharedcomponents.LevelWarning {
363			t.Errorf("level = %v, want LevelWarning", st.Level)
364		}
365		if !strings.Contains(strings.ToLower(st.Text), "approximate") {
366			t.Errorf("status = %q, want it to say the totals are approximate", st.Text)
367		}
368		if !strings.Contains(footerText(m), "approximate") {
369			t.Errorf("footer lacks the approximate warning:\n%s", footerText(m))
