379	func TestStatusPrecedenceAtTheAgentsLevel(t *testing.T) {
380		// loading wins over degraded
381		m := atAgents(t, degraded())
382		m.agentsLoading = true
383		if st := m.status(); !st.Spinner || strings.Contains(st.Text, "approximate") {
384			t.Errorf("loading + degraded = %+v, want the spinner line", st)
385		}
386		// error wins over loading and degraded
387		m.agentsErr = true
388		if st := m.status(); st.Level != sharedcomponents.LevelError || st.Spinner {
389			t.Errorf("error + loading + degraded = %+v, want the error", st)
