393	func TestADegradedUsageIsForgottenWhenAnotherSessionOpens(t *testing.T) {
394		m := atAgents(t, degraded())
395		m, _ = opened(t, feedBack(t, m), "right")
396		if strings.Contains(m.status().Text, "approximate") {
397			t.Errorf("a new session starts without the previous one's warning: %+v", m.status())
398		}
