401	// feedBack returns to the sessions level.
402	func feedBack(t *testing.T, m Model) Model {
403		t.Helper()
404		next, _ := opened(t, m, "esc")
405		if next.level != levelSessions {
406			t.Fatalf("fixture error: esc did not leave the agents level")
407		}
408		return next
409	}
410	
411	// ── Rule 114: help ───────────────────────────────────────────────────────────
412	
413	func TestHelpDocumentsTheAgentsLevel(t *testing.T) {
414		c := New(nil).GetHelpContent()
415		keys := map[string]bool{}
416		for _, b := range c.KeyBindings {
417			for _, k := range strings.Split(b.Key, "/") {
418				keys[strings.TrimSpace(k)] = true
419			}
420		}
421		for _, k := range []string{"→", "enter", "←", "esc", "ctrl+r", "/", ".", "?"} {
422			if !keys[k] {
423				t.Errorf("help lacks key %q", k)
424			}
425		}
426		var agents, privacy string
427		for _, s := range c.Sections {
428			switch s.Title {
429			case "Agents":
430				agents = strings.ToLower(s.Body)
431			case "Privacy":
432				privacy = strings.ToLower(s.Body)
433			}
434		}
435		if agents == "" {
436			t.Fatal("help needs a section titled Agents")
437		}
438		for _, want := range []string{"≥", "orchestrator", "approximate"} {
439			if !strings.Contains(agents, want) {
440				t.Errorf("the Agents section should mention %q", want)
441			}
442		}
443		for _, want := range []string{"token", "model", "never"} {
444			if !strings.Contains(privacy, want) {
445				t.Errorf("the Privacy section should now mention %q", want)
446			}
447		}
448		if strings.Contains(privacy, "only the working directory and the file date") {
449			t.Error("the Privacy section still claims nothing but the directory and the date is read")
450		}
451	}
452	
453	// stripANSI drops escape sequences so a position can be asserted on plain text.
454	func stripANSI(s string) string {
455		var b strings.Builder
456		for i := 0; i < len(s); i++ {
457			if s[i] == 0x1b {
458				for i < len(s) && s[i] != 'm' {
459					i++
460				}
461				continue
462			}
463			b.WriteByte(s[i])
464		}
465		return b.String()
466	}
