// TabItem represents a tab with its label
type TabItem struct {
	Label string
}

// RenderTabs generates a uniform tab bar
func RenderTabs(tabs []TabItem, activeIdx int) string {
	var result string
	for i, t := range tabs {
		label := " " + t.Label + " "
		if i > 0 {
			result += Bg(" ")
		}
		if i == activeIdx {
			result += ActiveTabStyle.Render(label)
		} else {
			result += InactiveTabStyle.Render(label)
		}
	}

	return result
}

